from urllib.parse import urlsplit, parse_qs
def parse_request_line(line):
    method, target, version = line.split(' ')
    u = urlsplit(target)
    query = {k: v[0] for k, v in parse_qs(u.query).items()}
    return (method, u.path, query, version)

def match(template, path):
    t = template.strip('/').split('/')
    p = path.strip('/').split('/')
    if len(t) != len(p):
        return None
    out = {}
    for a, b in zip(t, p):
        if a.startswith('{') and a.endswith('}'):
            out[a[1:-1]] = b
        elif a != b:
            return None
    return out

import json
def missing_fields(text, required):
    try:
        d = json.loads(text)
    except ValueError:
        return 'invalid'
    if not isinstance(d, dict):
        return 'invalid'
    return sorted(k for k in required if k not in d)

def check(schema, body):
    errs = []
    for k in schema['required']:
        if k not in body:
            errs.append(k + ': required')
    kinds = {'string': str, 'integer': int}
    for k, t in schema['properties'].items():
        if k in body:
            v = body[k]
            if not isinstance(v, kinds[t]) or isinstance(v, bool):
                errs.append(k + ': expected ' + t)
    return sorted(errs)

def page_after(items, after, limit):
    if after is None:
        return items[:limit]
    i = items.index(after)
    return items[i + 1:i + 1 + limit]

def total_charged(requests):
    seen, total = set(), 0
    for key, amount in requests:
        if key in seen:
            continue
        seen.add(key)
        total += amount
    return total

import hmac, hashlib
def sign(payload, key):
    return hmac.new(key.encode(), payload.encode(), hashlib.sha256).hexdigest()
def verify(payload, signature, key):
    return hmac.compare_digest(sign(payload, key), signature)

def token_bucket(capacity, rate, times):
    tokens, last, out = capacity, (times[0] if times else 0), []
    for t in times:
        tokens = min(capacity, tokens + (t - last) * rate)
        last = t
        if tokens >= 1:
            tokens -= 1
            out.append(True)
        else:
            out.append(False)
    return out

def emails_sent(events):
    seen, count = set(), 0
    for order_id, kind in events:
        if kind == 'paid' and order_id not in seen:
            seen.add(order_id)
            count += 1
    return count
